package com.employeeportal.model; import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="announcements") public class Announcement{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; String title; @Column(length=2000) String message; LocalDate publishedOn; String category; public Announcement(){} public Announcement(Long id,String t,String m,LocalDate d,String c){this.id=id;title=t;message=m;publishedOn=d;category=c;} public Long getId(){return id;} public void setId(Long v){id=v;} public String getTitle(){return title;} public String getMessage(){return message;} public LocalDate getPublishedOn(){return publishedOn;} public String getCategory(){return category;} }
